#include <iostream>
#include <vector>
#include <cmath>
using namespace std;
using ll = long long;

const int MOD = 998244353;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<ll> b(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> b[i];
    }

    // 前缀和 P 和二次前缀和 Q
    vector<ll> P(n + 1), Q(n + 1);
    for (int i = 1; i <= n; ++i) {
        P[i] = P[i-1] + b[i];
        Q[i] = Q[i-1] + P[i];
    }

    // G[k] = W(k) mod MOD
    vector<ll> G(n + 1);
    for (int k = 1; k <= n; ++k) {
        ll val = Q[n] - Q[k-1] - Q[n-k];
        val %= MOD;
        if (val < 0) val += MOD;
        G[k] = val;
    }

    // 埃氏筛
    vector<bool> isPrime(n + 1, true);
    if (n >= 0) isPrime[0] = false;
    if (n >= 1) isPrime[1] = false;
    for (int i = 2; i * i <= n; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }

    // 前缀和 h
    vector<ll> h(n + 1);
    for (int i = 1; i <= n; ++i) {
        h[i] = h[i-1] + (isPrime[i] ? G[i] : 0);
        if (h[i] >= MOD) h[i] -= MOD;
    }

    // 回答查询
    while (m--) {
        int l, r;
        cin >> l >> r;
        ll ans = (h[r] - h[l-1]) % MOD;
        if (ans < 0) ans += MOD;
        cout << ans << '\n';
    }

    return 0;
}
